sys_script_include.script:
var TBA_ScheduleEventsAjax = Class.create();

TBA_ScheduleEventsAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    /**
     * Fetches ALL booked schedule span events for a user.
     * Automatically finds all cmn_schedule records linked to the user
     * via x_travel_buddy_app_u_buddy_profile, then returns all spans.
     *
     * Parameters:
     *   sysparm_user_id (optional) - sys_id of a sys_user record.
     *                                Defaults to the current logged-in user.
     */
    getScheduleEvents: function() {
        var userId = this.getParameter('sysparm_user_id');

        // Default to current logged-in user if no user ID provided
        if (!userId) {
            userId = gs.getUserID();
        }

        var events = [];
        var scheduleIds = [];

        // Step 1: Find all schedules linked to this buddy/user
        var schedGR = new GlideRecord('cmn_schedule');
        schedGR.addQuery('x_travel_buddy_app_u_buddy_profile', userId);
        schedGR.query();

        while (schedGR.next()) {
            scheduleIds.push(schedGR.getUniqueValue());
        }

        // If no schedules found for this user, return empty
        if (scheduleIds.length === 0) {
            return JSON.stringify({ events: events, count: 0 });
        }

        // Step 2: Get all booked spans across all schedules for this user
        var spanGR = new GlideRecord('cmn_schedule_span');
        spanGR.addQuery('schedule', 'IN', scheduleIds.join(','));
        spanGR.addQuery('type', 'Booked');
        spanGR.query();

        while (spanGR.next()) {
            var startDT = spanGR.getValue('start_date_time') || '';
            var endDT = spanGR.getValue('end_date_time') || '';

            events.push({
                sys_id: spanGR.getUniqueValue(),
                name: spanGR.getValue('name') || '',
                start: this._convertScheduleDateTime(startDT),
                end: this._convertScheduleDateTime(endDT),
                type: spanGR.getValue('type') || '',
                show_as: spanGR.getValue('show_as') || '',
                all_day: spanGR.getValue('all_day') === '1',
                linked_trip: spanGR.getValue('x_travel_buddy_app_u_linked_trip') || '',
                schedule: spanGR.getValue('schedule') || ''
            });
        }

        return JSON.stringify({ events: events, count: events.length });
    },

    /**
     * One-time fix: Populates empty start/end fields on all cmn_schedule_span
     * records that have start_date_time/end_date_time but missing start/end.
     * Call this once to backfill existing records.
     * Returns the number of records fixed.
     */
    fixExistingRecords: function() {
        var gr = new GlideRecord('cmn_schedule_span');
        gr.addQuery('start_date_time', '!=', '');
        gr.addNullQuery('start');
        gr.query();

        var count = 0;
        while (gr.next()) {
            var startDT = gr.getValue('start_date_time') || '';
            var endDT = gr.getValue('end_date_time') || '';

            if (startDT && startDT.length >= 15) {
                gr.setValue('start', this._convertScheduleDateTime(startDT));
            }
            if (endDT && endDT.length >= 15) {
                gr.setValue('end', this._convertScheduleDateTime(endDT));
            }
            gr.update();
            count++;
        }

        return JSON.stringify({ fixed: count });
    },

    _convertScheduleDateTime: function(sdt) {
        if (!sdt || sdt.length < 15) return '';
        // Input format: "20260827T054920" (yyyyMMddTHHmmss)
        // Output format: "2026-08-27 05:49:20" (yyyy-MM-dd HH:mm:ss)
        var year = sdt.substring(0, 4);
        var month = sdt.substring(4, 6);
        var day = sdt.substring(6, 8);
        // Position 8 is 'T' separator
        var hour = sdt.substring(9, 11);
        var min = sdt.substring(11, 13);
        var sec = sdt.substring(13, 15);
        return year + '-' + month + '-' + day + ' ' + hour + ':' + min + ':' + sec;
    },

    type: 'TBA_ScheduleEventsAjax'
});
